-- Export the highest-ranked later-period test transactions for a responsive investigation report.
-- Run from the repository root with psql -X -v ON_ERROR_STOP=1 -d financial_crime -f sql/dashboard_export.sql
-- The output is generated data and is intentionally excluded from Git.
\copy (WITH ranked AS (SELECT transaction_id, review_score, data_split, model_version, row_number() OVER (ORDER BY review_score DESC, transaction_id) AS review_rank FROM (SELECT transaction_id, review_score, data_split, model_version FROM model_scores WHERE data_split = 'test' ORDER BY review_score DESC, transaction_id LIMIT 10000) top_scores) SELECT r.review_rank, r.transaction_id, r.review_score, r.data_split, r.model_version, t.transaction_time, t.from_bank, t.from_account, t.to_bank, t.to_account, t.amount_paid, t.payment_currency, t.amount_received, t.receiving_currency, t.payment_format, f.same_bank, f.self_transfer, f.transaction_hour, f.transaction_weekday, f.prior_transaction_count, f.prior_average_amount, f.has_prior_history, t.is_laundering FROM ranked r JOIN transactions t USING (transaction_id) JOIN model_features f USING (transaction_id) ORDER BY r.review_rank) TO 'data/processed/dashboard_cases_raw.csv' WITH (FORMAT csv, HEADER true)
